+bool parse_int_token(const std::string& s, int& out) {
+    if (s.empty()) {
+        return false;
+    }
+    char* end = nullptr;
+    long v = std::strtol(s.c_str(), &end, 10);
+    if (end == s.c_str() || *end != '\0') {
+        return false;
+    }
+    if (v < 0 || v > 1'000'000) {
+        return false;
+    }
+    out = static_cast<int>(v);
+    return true;
+}
