+std::string sanitize_name(std::string name) {
+    if (name.empty()) {
+        name = "default";
+    }
+    for (char& c : name) {
+        bool ok = (c >= 'a' && c <= 'z') ||
+                  (c >= 'A' && c <= 'Z') ||
+                  (c >= '0' && c <= '9') ||
+                  c == '_' || c == '-' || c == '.';
+        if (!ok) {
+            c = '_';
+        }
+    }
+    return name;
+}
