+    void drain_sig_pipe() {
+        std::array<uint8_t, 256> buf{};
+        while (true) {
+            ssize_t n = read(sig_pipe_[0], buf.data(), buf.size());
+            if (n > 0) {
+                continue;
+            }
+            if (n < 0 && errno == EINTR) {
+                continue;
+            }
+            break;
+        }
+    }
