+    void accept_new_clients() {
+        while (true) {
+            int cfd = accept(listen_fd_, nullptr, nullptr);
+            if (cfd < 0) {
+                if (errno == EINTR) {
+                    continue;
+                }
+                if (errno == EAGAIN || errno == EWOULDBLOCK) {
+                    break;
+                }
+                break;
+            }
+            if (!set_nonblocking(cfd)) {
+                close(cfd);
+                continue;
+            }
+            ClientState cs;
+            cs.fd = cfd;
+            clients_.emplace(cfd, std::move(cs));
+        }
+    }
