+        }
+        if (n == 0) {
+            peer_closed = true;
+            return true;
+        }
+        if (errno == EINTR) {
+            continue;
+        }
+        if (errno == EAGAIN || errno == EWOULDBLOCK) {
+            return true;
+        }
+        return false;
+    }
+}
+
+bool pop_one_frame(std::vector<uint8_t>& buf, FrameHeader& hdr, std::vector<uint8_t>& payload) {
+    if (buf.size() < sizeof(FrameHeader)) {
+        return false;
+    }
+
+    std::memcpy(&hdr, buf.data(), sizeof(FrameHeader));
+    if (hdr.length > kMaxFramePayload) {
+        hdr.type = 0;
+        hdr.length = 0;
+        return true;
+    }
+
+    size_t need = sizeof(FrameHeader) + static_cast<size_t>(hdr.length);
+    if (buf.size() < need) {
+        return false;
+    }
+
+    payload.clear();
+    if (hdr.length > 0) {
+        payload.insert(payload.end(),
+                       buf.begin() + static_cast<std::ptrdiff_t>(sizeof(FrameHeader)),
+                       buf.begin() + static_cast<std::ptrdiff_t>(need));
+    }
+
+    buf.erase(buf.begin(), buf.begin() + static_cast<std::ptrdiff_t>(need));
+    return true;
+}
+
+std::string trim(std::string s) {
+    while (!s.empty() && (s.back() == ' ' || s.back() == '\t' || s.back() == '\r' || s.back() == '\n')) {
+        s.pop_back();
+    }
+    size_t i = 0;
+    while (i < s.size() && (s[i] == ' ' || s[i] == '\t' || s[i] == '\r' || s[i] == '\n')) {
+        ++i;
+    }
+    if (i > 0) {
+        s.erase(0, i);
+    }
+    return s;
+}
+
+bool parse_int_token(const std::string& s, int& out) {
+    if (s.empty()) {
+        return false;
+    }
+    char* end = nullptr;
+    long v = std::strtol(s.c_str(), &end, 10);
+    if (end == s.c_str() || *end != '\0') {
+        return false;
+    }
+    if (v < 0 || v > 1'000'000) {
+        return false;
+    }
+    out = static_cast<int>(v);
+    return true;
+}
+
+std::string sanitize_name(std::string name) {
+    if (name.empty()) {
+        name = "default";
+    }
+    for (char& c : name) {
+        bool ok = (c >= 'a' && c <= 'z') ||
+                  (c >= 'A' && c <= 'Z') ||
+                  (c >= '0' && c <= '9') ||
+                  c == '_' || c == '-' || c == '.';
+        if (!ok) {
+            c = '_';
+        }
+    }
+    return name;
+}
+
+std::string socket_path_for_server(const std::string& server_name) {
+    uid_t uid = getuid();
+    std::string sanitized = sanitize_name(server_name);
+    return "/tmp/mini-tmux-" + std::to_string(static_cast<unsigned long long>(uid)) + "-" + sanitized + ".sock";
+}
+
+std::string detect_self_exe() {
+    std::array<char, 4096> buf{};
+    ssize_t n = readlink("/proc/self/exe", buf.data(), buf.size() - 1);
+    if (n <= 0) {
+        return "./mini-tmux";
+    }
+    buf[static_cast<size_t>(n)] = '\0';
+    return std::string(buf.data());
+}
+
+std::pair<int, int> terminal_size_or_default() {
+    winsize ws{};
+    if (ioctl(STDIN_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_row > 0 && ws.ws_col > 0) {
+        return {ws.ws_row, ws.ws_col};
+    }
+    return {24, 80};
+}
+
+void close_fd(int& fd) {
+    if (fd >= 0) {
+        close(fd);
+        fd = -1;
+    }
+}
+
+class RawModeGuard {
+public:
+    bool enable() {
+        if (!isatty(STDIN_FILENO)) {
+            return true;
+        }
+        if (tcgetattr(STDIN_FILENO, &old_) < 0) {
+            return false;
+        }
+        termios raw = old_;
+        cfmakeraw(&raw);
+        if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) < 0) {
+            return false;
+        }
+        active_ = true;
+        return true;
+    }
+
+    void restore() {
+        if (!active_) {
+            return;
+        }
+        (void)tcsetattr(STDIN_FILENO, TCSANOW, &old_);
+        active_ = false;
+    }
+
+    ~RawModeGuard() {
+        restore();
+    }
+
+private:
+    bool active_ = false;
+    termios old_{};
+};
+
+struct ClientState {
+    int fd = -1;
+    bool hello = false;
+    bool readonly = false;
+    int session_id = -1;
+    int rows = 24;
+    int cols = 80;
+    std::vector<uint8_t> inbuf;
+};
+
+struct SessionState {
+    int id = -1;
+    int master_fd = -1;
+    pid_t child_pid = -1;
+};
+
+class Server {
+public:
+    explicit Server(std::string socket_path)
+        : socket_path_(std::move(socket_path)) {}
+
+    bool init() {
+        if (signal(SIGPIPE, SIG_IGN) == SIG_ERR) {
+            return false;
+        }
+
+        listen_fd_ = socket(AF_UNIX, SOCK_STREAM, 0);
+        if (listen_fd_ < 0) {
+            return false;
+        }
+
+        sockaddr_un addr{};
+        addr.sun_family = AF_UNIX;
+        if (socket_path_.size() >= sizeof(addr.sun_path)) {
+            return false;
+        }
+        std::snprintf(addr.sun_path, sizeof(addr.sun_path), "%s", socket_path_.c_str());
+
+        unlink(socket_path_.c_str());
+        if (bind(listen_fd_, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) < 0) {
+            return false;
+        }
+        if (listen(listen_fd_, 64) < 0) {
+            return false;
+        }
+        if (!set_nonblocking(listen_fd_)) {
+            return false;
+        }
+
+        if (pipe(sig_pipe_) < 0) {
+            return false;
+        }
+        if (!set_nonblocking(sig_pipe_[0]) || !set_nonblocking(sig_pipe_[1])) {
+            return false;
+        }
+
+        g_sigchld_write_fd = sig_pipe_[1];
+        struct sigaction sa{};
+        sa.sa_handler = sigchld_handler;
+        sigemptyset(&sa.sa_mask);
+        sa.sa_flags = SA_RESTART | SA_NOCLDSTOP;
+        if (sigaction(SIGCHLD, &sa, nullptr) < 0) {
+            return false;
+        }
+
+        return true;
+    }
+
+    int run() {
+        if (!init()) {
+            return 1;
+        }
+
+        running_ = true;
+        while (running_) {
+            std::vector<pollfd> pfds;
+            pfds.reserve(2 + clients_.size() + sessions_.size());
+
+            pfds.push_back(pollfd{listen_fd_, POLLIN, 0});
+            pfds.push_back(pollfd{sig_pipe_[0], POLLIN, 0});
+
+            for (const auto& kv : clients_) {
+                pfds.push_back(pollfd{kv.first, POLLIN, 0});
+            }
+            for (const auto& kv : sessions_) {
+                pfds.push_back(pollfd{kv.second.master_fd, POLLIN, 0});
+            }
+
+            int pr = poll(pfds.data(), static_cast<nfds_t>(pfds.size()), 1000);
+            if (pr < 0) {
+                if (errno == EINTR) {
+                    continue;
+                }
+                break;
+            }
+
+            for (const auto& pfd : pfds) {
+                if (pfd.fd == listen_fd_ && (pfd.revents & POLLIN)) {
+                    accept_new_clients();
+                }
+            }
+
+            for (const auto& pfd : pfds) {
+                if (pfd.fd == sig_pipe_[0] && (pfd.revents & POLLIN)) {
+                    drain_sig_pipe();
+                    reap_children();
+                }
+            }
+
+            std::vector<int> client_fds;
+            client_fds.reserve(clients_.size());
+            for (const auto& kv : clients_) {
+                client_fds.push_back(kv.first);
+            }
+
+            for (int cfd : client_fds) {
+                short revents = 0;
+                for (const auto& pfd : pfds) {
+                    if (pfd.fd == cfd) {
+                        revents = pfd.revents;
+                        break;
+                    }
+                }
+                if (revents == 0) {
+                    continue;
+                }
+                if (revents & (POLLHUP | POLLERR | POLLNVAL)) {
+                    close_client(cfd);
+                    continue;
+                }
+                if (revents & POLLIN) {
+                    if (!handle_client_read(cfd)) {
+                        close_client(cfd);
+                    }
+                }
+            }
+
+            std::vector<int> session_master_fds;
+            session_master_fds.reserve(sessions_.size());
+            for (const auto& kv : sessions_) {
+                session_master_fds.push_back(kv.second.master_fd);
+            }
+
+            for (int mfd : session_master_fds) {
+                short revents = 0;
+                for (const auto& pfd : pfds) {
+                    if (pfd.fd == mfd) {
+                        revents = pfd.revents;
+                        break;
+                    }
+                }
+                if (revents == 0) {
+                    continue;
+                }
+                auto it_sid = master_to_session_.find(mfd);
+                if (it_sid == master_to_session_.end()) {
+                    continue;
+                }
+                int sid = it_sid->second;
+                if (revents & (POLLERR | POLLHUP | POLLNVAL | POLLIN)) {
+                    handle_session_master_read(sid);
+                }
+            }
+
+            reap_children();
+        }
+
+        cleanup();
+        return 0;
+    }
+
+private:
+    void cleanup() {
+        std::vector<int> cfd;
+        cfd.reserve(clients_.size());
+        for (const auto& kv : clients_) {
+            cfd.push_back(kv.first);
+        }
+        for (int fd : cfd) {
+            close_client(fd);
+        }
+
+        std::vector<int> sids;
+        sids.reserve(sessions_.size());
+        for (const auto& kv : sessions_) {
+            sids.push_back(kv.first);
+        }
+        for (int sid : sids) {
+            remove_session(sid);
+        }
+
+        close_fd(listen_fd_);
+        close_fd(sig_pipe_[0]);
+        close_fd(sig_pipe_[1]);
+        g_sigchld_write_fd = -1;
+
+        unlink(socket_path_.c_str());
+    }
+
+    void drain_sig_pipe() {
+        std::array<uint8_t, 256> buf{};
+        while (true) {
+            ssize_t n = read(sig_pipe_[0], buf.data(), buf.size());
+            if (n > 0) {
+                continue;
+            }
+            if (n < 0 && errno == EINTR) {
+                continue;
+            }
+            break;
+        }
+    }
+
+    void accept_new_clients() {
+        while (true) {
+            int cfd = accept(listen_fd_, nullptr, nullptr);
+            if (cfd < 0) {
+                if (errno == EINTR) {
+                    continue;
+                }
+                if (errno == EAGAIN || errno == EWOULDBLOCK) {
+                    break;
+                }
+                break;
+            }
+            if (!set_nonblocking(cfd)) {
+                close(cfd);
+                continue;
+            }
+            ClientState cs;
+            cs.fd = cfd;
+            clients_.emplace(cfd, std::move(cs));
+        }
+    }
+
+    bool handle_client_read(int cfd) {
+        auto it = clients_.find(cfd);
+        if (it == clients_.end()) {
+            return false;
+        }
+        ClientState& c = it->second;
+
+        bool peer_closed = false;
+        if (!read_into_buffer(c.fd, c.inbuf, peer_closed)) {
+            return false;
+        }
+        if (peer_closed) {
+            return false;
+        }
+
+        while (true) {
+            FrameHeader hdr{};
+            std::vector<uint8_t> payload;
+            if (!pop_one_frame(c.inbuf, hdr, payload)) {
+                break;
+            }
+            if (hdr.type == 0) {
+                return false;
+            }
+            if (!handle_client_frame(c, hdr, payload)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    bool handle_client_frame(ClientState& c, const FrameHeader& hdr, const std::vector<uint8_t>& payload) {
+        if (!c.hello) {
+            if (hdr.type != kMsgHello) {
+                return false;
+            }
+            return handle_hello(c, hdr, payload);
+        }
+
+        if (hdr.type == kMsgInput) {
+            if (c.readonly) {
+                return true;
+            }
+            auto sit = sessions_.find(c.session_id);
+            if (sit == sessions_.end()) {
+                return true;
+            }
+            if (!payload.empty()) {
+                if (!write_all_nb(sit->second.master_fd, payload.data(), payload.size())) {
+                    remove_session(c.session_id);
+                }
+            }
+            return true;
+        }
+
+        if (hdr.type == kMsgCmd) {
+            std::string cmd(payload.begin(), payload.end());
+            handle_command(c, cmd);
+            return true;
+        }
+
+        if (hdr.type == kMsgDetach) {
+            return false;
+        }
+
+        if (hdr.type == kMsgResize) {
+            if (payload.size() >= 8) {
+                uint32_t rows = 0;
+                uint32_t cols = 0;
+                std::memcpy(&rows, payload.data(), sizeof(uint32_t));
+                std::memcpy(&cols, payload.data() + 4, sizeof(uint32_t));
+                if (rows > 0 && cols > 0) {
+                    c.rows = static_cast<int>(rows);
+                    c.cols = static_cast<int>(cols);
+                    update_session_winsize(c.session_id);
+                }
+            }
+            return true;
+        }
+
+        return true;
+    }
+
+    bool handle_hello(ClientState& c, const FrameHeader& hdr, const std::vector<uint8_t>& payload) {
+        int rows = 24;
+        int cols = 80;
+        if (payload.size() >= 8) {
+            uint32_t r = 0;
+            uint32_t cc = 0;
+            std::memcpy(&r, payload.data(), sizeof(uint32_t));
+            std::memcpy(&cc, payload.data() + 4, sizeof(uint32_t));
+            if (r > 0) {
+                rows = static_cast<int>(r);
+            }
+            if (cc > 0) {
+                cols = static_cast<int>(cc);
+            }
+        }
+
+        c.rows = rows;
+        c.cols = cols;
+        c.readonly = (hdr.flags & kFlagReadonly) != 0;
+
+        int sid = -1;
+        bool want_new = (hdr.flags & kFlagCreateNewSession) != 0;
+        if (sessions_.empty() || want_new) {
+            sid = create_session(rows, cols);
+            if (sid < 0) {
+                send_frame_str(c.fd, kMsgError, 0, 0, "failed to create session");
+                return false;
+            }
+        } else {
+            sid = default_session_id();
+            if (sid < 0) {
+                return false;
+            }
+        }
+
+        c.session_id = sid;
+        c.hello = true;
+
+        std::vector<uint8_t> ack;
+        send_frame(c.fd, kMsgHelloAck, 0, static_cast<uint32_t>(sid), ack);
+        update_session_winsize(sid);
+        return true;
+    }
+
+    void handle_command(ClientState& c, const std::string& raw) {
+        std::string cmd = trim(raw);
+        if (cmd.empty()) {
+            return;
+        }
+
+        if (cmd == ":new") {
+            int sid = create_session(c.rows, c.cols);
+            if (sid >= 0) {
+                c.session_id = sid;
+                update_session_winsize(sid);
+            }
+            return;
+        }
+
+        if (cmd.rfind(":focus", 0) == 0) {
+            std::string arg = trim(cmd.substr(std::string(":focus").size()));
+            int sid = -1;
+            if (!parse_int_token(arg, sid)) {
+                return;
+            }
+            if (sessions_.count(sid) == 0) {
+                return;
+            }
+            c.session_id = sid;
+            update_session_winsize(sid);
+            return;
+        }
+
+        if (cmd.rfind(":kill", 0) == 0) {
+            std::string arg = trim(cmd.substr(std::string(":kill").size()));
+            int sid = -1;
+            if (!parse_int_token(arg, sid)) {
+                return;
+            }
+            auto it = sessions_.find(sid);
+            if (it == sessions_.end()) {
+                return;
+            }
+            if (it->second.child_pid > 0) {
+                (void)kill(-it->second.child_pid, SIGHUP);
+            }
+            remove_session(sid);
+            return;
+        }
+
+        if (cmd == ":detach") {
+            close_client(c.fd);
+            return;
+        }
+    }
+
+    int create_session(int rows, int cols) {
+        int master_fd = -1;
+        int slave_fd = -1;
+
+        winsize ws{};
+        ws.ws_row = static_cast<unsigned short>(std::max(1, rows));
+        ws.ws_col = static_cast<unsigned short>(std::max(1, cols));
+
+        if (openpty(&master_fd, &slave_fd, nullptr, nullptr, &ws) < 0) {
+            return -1;
+        }
+
+        pid_t pid = fork();
+        if (pid < 0) {
+            close(master_fd);
+            close(slave_fd);
+            return -1;
+        }
+
+        if (pid == 0) {
+            if (setsid() < 0) {
+                _exit(127);
+            }
+
+            (void)ioctl(slave_fd, TIOCSCTTY, 0);
+            (void)tcsetpgrp(slave_fd, getpid());
+
+            if (dup2(slave_fd, STDIN_FILENO) < 0 ||
+                dup2(slave_fd, STDOUT_FILENO) < 0 ||
+                dup2(slave_fd, STDERR_FILENO) < 0) {
+                _exit(127);
+            }
+
+            if (slave_fd > STDERR_FILENO) {
+                close(slave_fd);
+            }
+            close(master_fd);
+
+            long max_fd = sysconf(_SC_OPEN_MAX);
+            if (max_fd < 0) {
+                max_fd = 1024;
+            }
+            for (int fd = 3; fd < max_fd; ++fd) {
+                close(fd);
+            }
+
+            const char* shell = getenv("SHELL");
+            if (shell == nullptr || *shell == '\0') {
+                shell = "/bin/sh";
+            }
+            execl(shell, shell, "-i", static_cast<char*>(nullptr));
+            execl("/bin/sh", "/bin/sh", "-i", static_cast<char*>(nullptr));
+            _exit(127);
+        }
+
+        close(slave_fd);
+        if (!set_nonblocking(master_fd)) {
+            close(master_fd);
+            (void)kill(pid, SIGKILL);
+            (void)waitpid(pid, nullptr, 0);
+            return -1;
+        }
+
+        int sid = next_session_id_++;
+        SessionState s;
+        s.id = sid;
+        s.master_fd = master_fd;
+        s.child_pid = pid;
+
+        sessions_[sid] = s;
+        master_to_session_[master_fd] = sid;
+        pid_to_session_[pid] = sid;
+
+        return sid;
+    }
+
+    void handle_session_master_read(int sid) {
+        auto it = sessions_.find(sid);
+        if (it == sessions_.end()) {
+            return;
+        }
+
+        std::array<uint8_t, 65536> buf{};
+        while (true) {
+            ssize_t n = read(it->second.master_fd, buf.data(), buf.size());
+            if (n > 0) {
+                broadcast_output(sid, buf.data(), static_cast<size_t>(n));
+                continue;
+            }
+            if (n == 0) {
+                remove_session(sid);
+                return;
+            }
+            if (errno == EINTR) {
+                continue;
+            }
+            if (errno == EAGAIN || errno == EWOULDBLOCK) {
+                break;
+            }
+            if (errno == EIO) {
+                remove_session(sid);
+                return;
+            }
+            remove_session(sid);
+            return;
+        }
+    }
+
+    void broadcast_output(int sid, const uint8_t* data, size_t len) {
+        std::vector<uint8_t> payload(data, data + len);
+        std::vector<int> dead;
+        for (const auto& kv : clients_) {
+            const ClientState& c = kv.second;
+            if (!c.hello || c.session_id != sid) {
+                continue;
+            }
+            if (!send_frame(c.fd, kMsgOutput, 0, 0, payload)) {
+                dead.push_back(c.fd);
+            }
+        }
+        for (int fd : dead) {
+            close_client(fd);
+        }
+    }
+
+    void reap_children() {
+        while (true) {
+            int status = 0;
+            pid_t pid = waitpid(-1, &status, WNOHANG);
+            if (pid == 0) {
+                break;
+            }
+            if (pid < 0) {
+                if (errno == EINTR) {
+                    continue;
+                }
+                break;
+            }
+
+            auto it = pid_to_session_.find(pid);
+            if (it != pid_to_session_.end()) {
+                int sid = it->second;
+                remove_session(sid);
+            }
+        }
+    }
+
+    void remove_session(int sid) {
+        auto it = sessions_.find(sid);
+        if (it == sessions_.end()) {
+            return;
+        }
+
+        int master_fd = it->second.master_fd;
+        pid_t child_pid = it->second.child_pid;
+
+        close_fd(master_fd);
+        master_to_session_.erase(it->second.master_fd);
+        if (child_pid > 0) {
+            pid_to_session_.erase(child_pid);
+        }
+        sessions_.erase(it);
+
+        std::vector<int> affected;
+        for (const auto& kv : clients_) {
+            if (kv.second.hello && kv.second.session_id == sid) {
+                affected.push_back(kv.first);
+            }
+        }
+
+        if (sessions_.empty()) {
+            for (int fd : affected) {
+                close_client(fd);
+            }
+            running_ = false;
+            return;
+        }
+
+        int fallback_sid = default_session_id();
+        for (int fd : affected) {
+            auto cit = clients_.find(fd);
+            if (cit != clients_.end()) {
+                cit->second.session_id = fallback_sid;
+            }
+        }
+        update_session_winsize(fallback_sid);
+    }
+
+    int default_session_id() const {
+        if (sessions_.empty()) {
+            return -1;
+        }
+        return sessions_.begin()->first;
+    }
+
+    void update_session_winsize(int sid) {
+        auto sit = sessions_.find(sid);
+        if (sit == sessions_.end()) {
+            return;
+        }
+
+        bool has_client = false;
+        int min_rows = 0;
+        int min_cols = 0;
+
+        for (const auto& kv : clients_) {
+            const ClientState& c = kv.second;
+            if (!c.hello || c.session_id != sid) {
+                continue;
+            }
+            if (!has_client) {
+                min_rows = c.rows;
+                min_cols = c.cols;
+                has_client = true;
+            } else {
+                min_rows = std::min(min_rows, c.rows);
+                min_cols = std::min(min_cols, c.cols);
+            }
+        }
+
+        if (!has_client) {
+            return;
+        }
+
+        min_rows = std::max(min_rows, 1);
+        min_cols = std::max(min_cols, 1);
+
+        winsize ws{};
+        ws.ws_row = static_cast<unsigned short>(min_rows);
+        ws.ws_col = static_cast<unsigned short>(min_cols);
+
+        (void)ioctl(sit->second.master_fd, TIOCSWINSZ, &ws);
+        if (sit->second.child_pid > 0) {
+            (void)kill(-sit->second.child_pid, SIGWINCH);
+        }
+    }
+
+    void close_client(int cfd) {
+        auto it = clients_.find(cfd);
+        if (it == clients_.end()) {
+            return;
+        }
+
+        int sid = it->second.session_id;
+        close_fd(it->second.fd);
+        clients_.erase(it);
+
+        update_session_winsize(sid);
+    }
+
+    std::string socket_path_;
+    int listen_fd_ = -1;
+    int sig_pipe_[2] = {-1, -1};
+    bool running_ = false;
+
+    std::map<int, ClientState> clients_;
+    std::map<int, SessionState> sessions_;
+    std::map<int, int> master_to_session_;
+    std::map<pid_t, int> pid_to_session_;
+    int next_session_id_ = 0;
+};
+
+bool connect_to_socket_once(const std::string& sock_path, int& out_fd) {
+    out_fd = socket(AF_UNIX, SOCK_STREAM, 0);
+    if (out_fd < 0) {
+        return false;
+    }
+
+    sockaddr_un addr{};
+    addr.sun_family = AF_UNIX;
+    if (sock_path.size() >= sizeof(addr.sun_path)) {
+        close_fd(out_fd);
+        errno = ENAMETOOLONG;
+        return false;
+    }
+    std::snprintf(addr.sun_path, sizeof(addr.sun_path), "%s", sock_path.c_str());
+
+    if (connect(out_fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) < 0) {
+        close_fd(out_fd);
+        return false;
+    }
+
+    if (!set_nonblocking(out_fd)) {
+        close_fd(out_fd);
+        return false;
+    }
+
+    return true;
+}
+
+bool connect_with_retry(const std::string& sock_path, int& out_fd, int attempts, int sleep_ms) {
+    for (int i = 0; i < attempts; ++i) {
+        if (connect_to_socket_once(sock_path, out_fd)) {
+            return true;
+        }
+        int err = errno;
+        if (err != ENOENT && err != ECONNREFUSED && err != EAGAIN) {
+            return false;
+        }
+        usleep(static_cast<useconds_t>(sleep_ms * 1000));
+    }
+    return false;
+}
+
+bool spawn_server_process(const std::string& self_exe) {
+    pid_t pid = fork();
+    if (pid < 0) {
+        return false;
+    }
+    if (pid == 0) {
+        if (setsid() < 0) {
+            _exit(127);
+        }
+        execl(self_exe.c_str(), self_exe.c_str(), "--server", static_cast<char*>(nullptr));
+        _exit(127);
+    }
+    return true;
+}
+
+struct InputState {
+    bool cmd_mode = false;
+    bool prefix_pending = false;
+    bool line_start = true;
+    bool swallow_lf = false;
+    std::string cmd;
+};
+
+bool send_resize_frame(int sock_fd) {
+    auto [rows, cols] = terminal_size_or_default();
+    uint32_t r = static_cast<uint32_t>(rows);
+    uint32_t c = static_cast<uint32_t>(cols);
+    std::vector<uint8_t> payload(8);
+    std::memcpy(payload.data(), &r, sizeof(uint32_t));
+    std::memcpy(payload.data() + 4, &c, sizeof(uint32_t));
+    return send_frame(sock_fd, kMsgResize, 0, 0, payload);
+}
+
+bool process_input_bytes(int sock_fd, const uint8_t* data, size_t len, InputState& st, bool readonly) {
+    for (size_t i = 0; i < len; ++i) {
+        uint8_t b = data[i];
+
+        if (st.swallow_lf && b == '\n') {
+            st.swallow_lf = false;
+            st.line_start = true;
+            continue;
+        }
+        st.swallow_lf = false;
+
+        if (st.cmd_mode) {
+            if (b == '\r' || b == '\n') {
+                if (!send_frame_str(sock_fd, kMsgCmd, 0, 0, st.cmd)) {
+                    return false;
+                }
+                st.cmd.clear();
+                st.cmd_mode = false;
+                st.line_start = true;
+                if (b == '\r') {
+                    st.swallow_lf = true;
+                }
+                continue;
+            }
+            if (b == 0x7f || b == 0x08) {
+                if (!st.cmd.empty() && st.cmd.size() > 1) {
+                    st.cmd.pop_back();
+                }
+                continue;
+            }
+            if (b >= 32 && b <= 126) {
+                st.cmd.push_back(static_cast<char>(b));
+            }
+            continue;
+        }
+
+        if (st.prefix_pending) {
+            st.prefix_pending = false;
+            if (b == 'd' || b == 'D') {
+                std::vector<uint8_t> no_payload;
+                send_frame(sock_fd, kMsgDetach, 0, 0, no_payload);
+                return false;
+            }
+            if (b == ':') {
+                st.cmd_mode = true;
+                st.cmd = ":";
+                continue;
+            }
+            if (b == 'n' || b == 'p') {
+                continue;
+            }
+            if (!readonly) {
+                std::vector<uint8_t> payload;
+                payload.push_back(0x02);
+                payload.push_back(b);
+                if (!send_frame(sock_fd, kMsgInput, 0, 0, payload)) {
+                    return false;
+                }
+            }
+            st.line_start = (b == '\r' || b == '\n');
+            if (b == '\r') {
+                st.swallow_lf = true;
+            }
+            continue;
+        }
+
+        if (b == 0x02) {
+            st.prefix_pending = true;
+            continue;
+        }
+
+        if (st.line_start && b == ':') {
+            st.cmd_mode = true;
+            st.cmd = ":";
+            continue;
+        }
+
+        if (!readonly) {
+            std::vector<uint8_t> payload(1, b);
+            if (!send_frame(sock_fd, kMsgInput, 0, 0, payload)) {
+                return false;
+            }
+        }
+
+        st.line_start = (b == '\r' || b == '\n');
+        if (b == '\r') {
+            st.swallow_lf = true;
+        }
+    }
+
+    return true;
+}
+
+int run_client(const std::string& socket_path, bool attach_mode, bool readonly_mode) {
+    int sock_fd = -1;
+
+    bool connected = connect_to_socket_once(socket_path, sock_fd);
+    bool started_server = false;
+
+    if (!connected) {
+        if (attach_mode) {
+            std::fprintf(stderr, "mini-tmux: no server to attach\n");
+            return 1;
+        }
+        std::string self_exe = detect_self_exe();
+        if (!spawn_server_process(self_exe)) {
+            std::fprintf(stderr, "mini-tmux: failed to spawn server\n");
+            return 1;
+        }
+        started_server = true;
+        if (!connect_with_retry(socket_path, sock_fd, 120, 50)) {
+            std::fprintf(stderr, "mini-tmux: failed to connect to server\n");
+            return 1;
+        }
+    }
+
+    uint32_t flags = 0;
+    if (readonly_mode) {
+        flags |= kFlagReadonly;
+    }
+    if (!attach_mode && !started_server) {
+        flags |= kFlagCreateNewSession;
+    }
+
+    auto [rows, cols] = terminal_size_or_default();
+    uint32_t r = static_cast<uint32_t>(rows);
+    uint32_t c = static_cast<uint32_t>(cols);
+    std::vector<uint8_t> hello_payload(8);
+    std::memcpy(hello_payload.data(), &r, sizeof(uint32_t));
+    std::memcpy(hello_payload.data() + 4, &c, sizeof(uint32_t));
+
+    if (!send_frame(sock_fd, kMsgHello, flags, 0, hello_payload)) {
+        std::fprintf(stderr, "mini-tmux: failed to send hello\n");
+        close_fd(sock_fd);
+        return 1;
+    }
+
+    RawModeGuard raw;
+    if (!raw.enable()) {
+        std::fprintf(stderr, "mini-tmux: failed to enable raw mode\n");
+        close_fd(sock_fd);
+        return 1;
+    }
+
+    int winch_pipe[2] = {-1, -1};
+    if (pipe(winch_pipe) == 0) {
+        set_nonblocking(winch_pipe[0]);
+        set_nonblocking(winch_pipe[1]);
+        g_sigwinch_write_fd = winch_pipe[1];
+
+        struct sigaction sa{};
+        sa.sa_handler = sigwinch_handler;
+        sigemptyset(&sa.sa_mask);
+        sa.sa_flags = SA_RESTART;
+        sigaction(SIGWINCH, &sa, nullptr);
+    }
+
+    signal(SIGPIPE, SIG_IGN);
+
+    std::vector<uint8_t> sock_buf;
+    InputState input_state;
+
+    bool running = true;
+    while (running) {
+        pollfd pfds[3]{};
+        nfds_t nfd = 0;
+
+        pfds[nfd++] = pollfd{STDIN_FILENO, POLLIN, 0};
+        pfds[nfd++] = pollfd{sock_fd, POLLIN, 0};
+        if (winch_pipe[0] >= 0) {
+            pfds[nfd++] = pollfd{winch_pipe[0], POLLIN, 0};
+        }
+
+        int pr = poll(pfds, nfd, -1);
+        if (pr < 0) {
+            if (errno == EINTR) {
+                continue;
+            }
+            break;
+        }
+
+        if (pfds[0].revents & POLLIN) {
+            std::array<uint8_t, 4096> in{};
+            ssize_t n = read(STDIN_FILENO, in.data(), in.size());
+            if (n <= 0) {
+                running = false;
+            } else {
+                if (!process_input_bytes(sock_fd, in.data(), static_cast<size_t>(n), input_state, readonly_mode)) {
+                    running = false;
+                }
+            }
+        }
+
+        if (pfds[1].revents & (POLLHUP | POLLERR | POLLNVAL)) {
+            running = false;
+        } else if (pfds[1].revents & POLLIN) {
+            bool peer_closed = false;
+            if (!read_into_buffer(sock_fd, sock_buf, peer_closed) || peer_closed) {
+                running = false;
+            } else {
+                while (true) {
+                    FrameHeader hdr{};
+                    std::vector<uint8_t> payload;
+                    if (!pop_one_frame(sock_buf, hdr, payload)) {
+                        break;
+                    }
+                    if (hdr.type == 0) {
+                        running = false;
+                        break;
+                    }
+                    if (hdr.type == kMsgOutput) {
+                        if (!payload.empty()) {
+                            if (!write_all_nb(STDOUT_FILENO, payload.data(), payload.size())) {
+                                running = false;
+                                break;
+                            }
+                        }
+                    } else if (hdr.type == kMsgError) {
+                        std::string msg(payload.begin(), payload.end());
+                        std::string out = "mini-tmux server error: " + msg + "\n";
+                        (void)write_all_nb(STDERR_FILENO,
+                                           reinterpret_cast<const uint8_t*>(out.data()),
+                                           out.size());
+                    }
+                }
+            }
+        }
+
+        if (nfd >= 3 && (pfds[2].revents & POLLIN)) {
+            std::array<uint8_t, 256> tmp{};
+            while (true) {
+                ssize_t n = read(winch_pipe[0], tmp.data(), tmp.size());
+                if (n > 0) {
+                    continue;
+                }
+                if (n < 0 && errno == EINTR) {
+                    continue;
+                }
+                break;
+            }
+            if (!send_resize_frame(sock_fd)) {
+                running = false;
+            }
+        }
+    }
+
+    raw.restore();
+
+    if (winch_pipe[0] >= 0) {
+        close_fd(winch_pipe[0]);
+    }
+    if (winch_pipe[1] >= 0) {
+        close_fd(winch_pipe[1]);
+    }
+    g_sigwinch_write_fd = -1;
+
+    close_fd(sock_fd);
+    return 0;
+}
+
+void usage() {
+    std::fprintf(stderr,
+                 "Usage:\n"
+                 "  mini-tmux\n"
+                 "  mini-tmux attach\n"
+                 "  mini-tmux attach -r\n");
+}
+
+}  // namespace
+
+int main(int argc, char** argv) {
+    std::string server_name = "default";
+    if (const char* env = std::getenv("MINI_TMUX_SERVER")) {
+        server_name = env;
+    }
+
+    std::string sock_path = socket_path_for_server(server_name);
+
+    if (argc >= 2 && std::string(argv[1]) == "--server") {
+        Server server(sock_path);
+        return server.run();
+    }
+
+    bool attach_mode = false;
+    bool readonly_mode = false;
+
+    if (argc == 1) {
+        attach_mode = false;
+    } else if (argc >= 2 && std::string(argv[1]) == "attach") {
+        attach_mode = true;
+        if (argc == 3 && std::string(argv[2]) == "-r") {
+            readonly_mode = true;
+        } else if (argc != 2) {
+            usage();
+            return 1;
+        }
+    } else {
+        usage();
+        return 1;
+    }
+
+    return run_client(sock_path, attach_mode, readonly_mode);
+}
