+std::string socket_path_for_server(const std::string& server_name) {
+    uid_t uid = getuid();
+    std::string sanitized = sanitize_name(server_name);
+    return "/tmp/mini-tmux-" + std::to_string(static_cast<unsigned long long>(uid)) + "-" + sanitized + ".sock";
+}
