+class RawModeGuard {
+public:
+    bool enable() {
+        if (!isatty(STDIN_FILENO)) {
+            return true;
+        }
+        if (tcgetattr(STDIN_FILENO, &old_) < 0) {
+            return false;
+        }
+        termios raw = old_;
+        cfmakeraw(&raw);
+        if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) < 0) {
+            return false;
+        }
+        active_ = true;
+        return true;
+    }
+
+    void restore() {
+        if (!active_) {
+            return;
+        }
+        (void)tcsetattr(STDIN_FILENO, TCSANOW, &old_);
+        active_ = false;
+    }
+
+    ~RawModeGuard() {
+        restore();
+    }
+
+private:
+    bool active_ = false;
+    termios old_{};
+};
