+    raw.restore();
+
+    if (winch_pipe[0] >= 0) {
+        close_fd(winch_pipe[0]);
+    }
+    if (winch_pipe[1] >= 0) {
+        close_fd(winch_pipe[1]);
+    }
+    g_sigwinch_write_fd = -1;
+
+    close_fd(sock_fd);
+    return 0;
+}
+
+void usage() {
+    std::fprintf(stderr,
+                 "Usage:\n"
+                 "  mini-tmux\n"
+                 "  mini-tmux attach\n"
+                 "  mini-tmux attach -r\n");
+}
+
+}  // namespace
+
+int main(int argc, char** argv) {
+    std::string server_name = "default";
+    if (const char* env = std::getenv("MINI_TMUX_SERVER")) {
+        server_name = env;
+    }
