+        if (!p.current_line.empty()) {
+            write_best_effort_nb(fd,
+                                 reinterpret_cast<const uint8_t*>(p.current_line.data()),
+                                 p.current_line.size());
+            static const uint8_t nl = '\n';
+            write_best_effort_nb(fd, &nl, 1);
