+    void handle_command(ClientState& c, const std::string& raw) {
+        std::string cmd = trim(raw);
+        if (cmd.empty()) {
+            return;
+        }
+
+        SessionState* s = get_session(c.session_id);
+        if (s == nullptr) {
+            return;
+        }
+
+        if (cmd == ":detach") {
+            close_client(c.fd);
+            return;
+        }
+
+        if (cmd == ":new") {
+            (void)create_pane(c.session_id);
+            return;
+        }
+
+        if (cmd == ":focus-next") {
+            focus_next(*s, true);
+            return;
+        }
+        if (cmd == ":focus-prev") {
+            focus_next(*s, false);
+            return;
+        }
