+bool process_input_bytes(int sock_fd, const uint8_t* data, size_t len, InputState& st, bool readonly) {
+    for (size_t i = 0; i < len; ++i) {
+        uint8_t b = data[i];
+
+        if (st.swallow_lf && b == '\n') {
+            st.swallow_lf = false;
+            st.line_start = true;
+            continue;
+        }
+        st.swallow_lf = false;
+
+        if (st.cmd_mode) {
+            if (b == '\r' || b == '\n') {
+                if (!readonly) {
+                    if (!send_frame_str(sock_fd, kMsgCmd, 0, 0, st.cmd)) {
+                        return false;
+                    }
+                }
+                st.cmd.clear();
+                st.cmd_mode = false;
+                st.line_start = true;
+                if (b == '\r') {
+                    st.swallow_lf = true;
+                }
+                continue;
+            }
+            if (b == 0x7f || b == 0x08) {
+                if (!st.cmd.empty() && st.cmd.size() > 1) {
+                    st.cmd.pop_back();
+                }
+                continue;
+            }
+            if (b >= 32 && b <= 126) {
+                st.cmd.push_back(static_cast<char>(b));
+            }
+            continue;
+        }
+
+        if (st.prefix_pending) {
+            st.prefix_pending = false;
+            if (b == 'd' || b == 'D') {
+                std::vector<uint8_t> no_payload;
+                (void)send_frame(sock_fd, kMsgDetach, 0, 0, no_payload);
+                return false;
+            }
+            if (b == ':') {
+                st.cmd_mode = true;
+                st.cmd = ":";
+                continue;
+            }
+            if (b == 'n' || b == 'N') {
+                if (!readonly) {
+                    if (!send_frame_str(sock_fd, kMsgCmd, 0, 0, ":focus-next")) {
+                        return false;
+                    }
+                }
+                continue;
+            }
+            if (b == 'p' || b == 'P') {
+                if (!readonly) {
+                    if (!send_frame_str(sock_fd, kMsgCmd, 0, 0, ":focus-prev")) {
+                        return false;
+                    }
+                }
+                continue;
+            }
+            if (!readonly) {
+                std::vector<uint8_t> payload;
+                payload.push_back(0x02);
+                payload.push_back(b);
+                if (!send_frame(sock_fd, kMsgInput, 0, 0, payload)) {
+                    return false;
+                }
+            }
+            st.line_start = (b == '\r' || b == '\n');
+            if (b == '\r') {
+                st.swallow_lf = true;
+            }
+            continue;
+        }
+
+        if (b == 0x02) {
+            st.prefix_pending = true;
+            continue;
+        }
+
+        if (st.line_start && b == ':') {
+            st.cmd_mode = true;
+            st.cmd = ":";
+            continue;
+        }
+
+        if (!readonly) {
+            std::vector<uint8_t> payload(1, b);
+            if (!send_frame(sock_fd, kMsgInput, 0, 0, payload)) {
+                return false;
+            }
+        }
+
+        st.line_start = (b == '\r' || b == '\n');
+        if (b == '\r') {
+            st.swallow_lf = true;
+        }
+    }
+
+    return true;
